CREATE TABLE IF NOT EXISTS sp_migrations(version INT PRIMARY KEY, applied_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sp_users(id CHAR(36) PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,password_hash VARCHAR(255) NOT NULL,roles JSON NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sp_sessions(token_hash CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,csrf CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES sp_users(id));
CREATE TABLE IF NOT EXISTS sp_customers(id CHAR(36) PRIMARY KEY,name VARCHAR(160) NOT NULL,industry VARCHAR(100) NOT NULL,contact VARCHAR(160) NOT NULL,owner_id CHAR(36) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(owner_id) REFERENCES sp_users(id));
CREATE TABLE IF NOT EXISTS sp_products(id CHAR(36) PRIMARY KEY,code VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL,cas VARCHAR(80) NOT NULL,description TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS sp_proposals(id CHAR(36) PRIMARY KEY,code VARCHAR(60) UNIQUE NOT NULL,title VARCHAR(160) NOT NULL,customer_id CHAR(36) NOT NULL,owner_id CHAR(36) NOT NULL,created_by CHAR(36) NOT NULL,scene VARCHAR(200) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',edition INT NOT NULL DEFAULT 1,revision INT NOT NULL DEFAULT 1,body JSON NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES sp_customers(id),FOREIGN KEY(owner_id) REFERENCES sp_users(id));
CREATE TABLE IF NOT EXISTS sp_proposal_versions(id BIGINT AUTO_INCREMENT PRIMARY KEY,proposal_id CHAR(36) NOT NULL,edition INT NOT NULL,revision INT NOT NULL,snapshot JSON NOT NULL,actor_id CHAR(36) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(proposal_id,edition,revision));
CREATE TABLE IF NOT EXISTS sp_approval_requests(id CHAR(36) PRIMARY KEY,proposal_id CHAR(36) NOT NULL,edition INT NOT NULL,revision INT NOT NULL,snapshot JSON NOT NULL,snapshot_hash CHAR(64) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',note TEXT NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),INDEX(proposal_id));
CREATE TABLE IF NOT EXISTS sp_approval_steps(id CHAR(36) PRIMARY KEY,request_id CHAR(36) NOT NULL,role VARCHAR(20) NOT NULL,assignee_id CHAR(36) NOT NULL,status VARCHAR(30) NOT NULL,comment TEXT,decided_at DATETIME(3),UNIQUE(request_id,role),FOREIGN KEY(request_id) REFERENCES sp_approval_requests(id));
CREATE TABLE IF NOT EXISTS sp_exports(id CHAR(36) PRIMARY KEY,proposal_id CHAR(36) NOT NULL,request_id CHAR(36) NOT NULL,actor_id CHAR(36) NOT NULL,format VARCHAR(20) NOT NULL,sha256 CHAR(64) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sp_audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id CHAR(36) NOT NULL,proposal_id CHAR(36),action VARCHAR(80) NOT NULL,details JSON NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sp_documents(id CHAR(36) PRIMARY KEY,title VARCHAR(200) NOT NULL,kind VARCHAR(30) NOT NULL,proposal_id CHAR(36) NULL,created_by CHAR(36) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(proposal_id) REFERENCES sp_proposals(id),FOREIGN KEY(created_by) REFERENCES sp_users(id),INDEX(proposal_id));
CREATE TABLE IF NOT EXISTS sp_document_versions(id CHAR(36) PRIMARY KEY,document_id CHAR(36) NOT NULL,version INT NOT NULL,filename VARCHAR(240) NOT NULL,sha256 CHAR(64) NOT NULL,storage_provider VARCHAR(20) NOT NULL,storage_key VARCHAR(200) NOT NULL,byte_size BIGINT UNSIGNED NOT NULL,text_content MEDIUMTEXT NOT NULL,parse_notes JSON NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',allow_model BOOLEAN NOT NULL DEFAULT FALSE,expires_on DATE NULL,created_by CHAR(36) NOT NULL,reviewed_by CHAR(36) NULL,review_note TEXT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),reviewed_at DATETIME(3) NULL,UNIQUE(document_id,version),FOREIGN KEY(document_id) REFERENCES sp_documents(id),INDEX(status));
CREATE TABLE IF NOT EXISTS sp_review_assignments(owner_id CHAR(36) PRIMARY KEY,chemist_id CHAR(36) NOT NULL,compliance_id CHAR(36) NOT NULL,leader_id CHAR(36) NOT NULL,revision INT NOT NULL DEFAULT 1,FOREIGN KEY(owner_id) REFERENCES sp_users(id));
CREATE TABLE IF NOT EXISTS sp_jobs(id CHAR(36) PRIMARY KEY,proposal_id CHAR(36) NOT NULL,requested_by CHAR(36) NOT NULL,request_key CHAR(36) NOT NULL,request_hash CHAR(64) NOT NULL,input_snapshot JSON NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',result_json JSON NULL,usage_json JSON NULL,error_message VARCHAR(500) NULL,cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),started_at DATETIME(3) NULL,finished_at DATETIME(3) NULL,applied_at DATETIME(3) NULL,UNIQUE(proposal_id,request_key),INDEX(status,created_at),FOREIGN KEY(proposal_id) REFERENCES sp_proposals(id));
CREATE TABLE IF NOT EXISTS sp_job_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id CHAR(36) NOT NULL,type VARCHAR(30) NOT NULL,payload JSON NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),INDEX(job_id,id),FOREIGN KEY(job_id) REFERENCES sp_jobs(id));
CREATE TABLE IF NOT EXISTS sp_product_specs(id CHAR(36) PRIMARY KEY,product_id CHAR(36) NOT NULL,version INT NOT NULL,parameters JSON NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by CHAR(36) NOT NULL,reviewed_by CHAR(36) NULL,review_note TEXT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),reviewed_at DATETIME(3) NULL,UNIQUE(product_id,version),FOREIGN KEY(product_id) REFERENCES sp_products(id));
CREATE TABLE IF NOT EXISTS sp_artifacts(id CHAR(36) PRIMARY KEY,request_id CHAR(36) NOT NULL,format VARCHAR(10) NOT NULL,renderer_version VARCHAR(30) NOT NULL,sha256 CHAR(64) NOT NULL,storage_provider VARCHAR(20) NOT NULL,storage_key VARCHAR(200) NOT NULL,byte_size BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(request_id,format),FOREIGN KEY(request_id) REFERENCES sp_approval_requests(id));
CREATE TABLE IF NOT EXISTS sp_templates(id CHAR(36) PRIMARY KEY,family_id CHAR(36) NOT NULL,version INT NOT NULL,name VARCHAR(100) NOT NULL,industry VARCHAR(100) NOT NULL,definition JSON NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_by CHAR(36) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sp_risks(id CHAR(36) PRIMARY KEY,proposal_id CHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,owner_id CHAR(36) NOT NULL,blocking BOOLEAN NOT NULL,evidence JSON NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',note TEXT,revision INT NOT NULL DEFAULT 1,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),INDEX(proposal_id));
CREATE TABLE IF NOT EXISTS sp_requirement_batches(id CHAR(36) PRIMARY KEY,proposal_id CHAR(36) NOT NULL,edition INT NOT NULL,revision INT NOT NULL,created_by CHAR(36) NOT NULL,candidates JSON NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),applied_at DATETIME(3) NULL,INDEX(proposal_id));
